{
  "name": "@cultivx/codereach",
  "version": "0.2.34",
  "description": "Drive a local OpenCode session from your phone. Run one command; scan a QR.",
  "license": "MIT",
  "author": "CodeReach contributors",
  "homepage": "https://github.com/CultivX/codereach/tree/main/packages/agent#readme",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/CultivX/codereach.git",
    "directory": "packages/agent"
  },
  "bugs": {
    "url": "https://github.com/CultivX/codereach/issues"
  },
  "keywords": [
    "codereach",
    "opencode",
    "remote-control",
    "cli",
    "qr",
    "phone"
  ],
  "type": "module",
  "bin": {
    "codereach": "bin/codereach.mjs"
  },
  "main": "src/index.ts",
  "types": "src/index.ts",
  "exports": {
    ".": "./src/index.ts"
  },
  "files": [
    "bin",
    "dist",
    "src",
    "README.md",
    "!**/*.test.ts",
    "!src/e2e-phone.ts",
    "!dist/e2e-phone.mjs",
    "!dist/e2e-phone.mjs.map",
    "!dist/*.map"
  ],
  "engines": {
    "node": ">=22.0.0"
  },
  "publishConfig": {
    "access": "public",
    "provenance": true
  },
  "scripts": {
    "build": "tsup",
    "test": "vitest run",
    "typecheck": "tsc --noEmit",
    "lint": "eslint src",
    "clean": "rm -rf dist",
    "dev": "tsup --watch"
  },
  "dependencies": {
    "@noble/curves": "^2.4.0",
    "commander": "^15.0.0",
    "qrcode-terminal": "^0.12.0",
    "transcribe-cpp": "0.4.1",
    "yaml": "^2.9.1"
  }
}
